import{_ as a,c as r,o as t,ag as i}from"./chunks/framework.B-XtCDNB.js";const c=JSON.parse('{"title":"Genie Tutorials, Blogs and Code Examples","description":"Genie Tutorials, Blogs and Code Examples This page provides links to tutorials, blog posts and code examples of the Genie programming language. It has been ported from the now-retired GNOME Wiki...","frontmatter":{},"headers":[],"relativePath":"genie/resources.md","filePath":"genie/resources.md","lastUpdated":1785795526000}'),o={name:"genie/resources.md"};function n(l,e,s,h,g,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="genie-tutorials-blogs-and-code-examples" tabindex="-1">Genie Tutorials, Blogs and Code Examples <a class="header-anchor" href="#genie-tutorials-blogs-and-code-examples" aria-label="Permalink to &quot;Genie Tutorials, Blogs and Code Examples&quot;">​</a></h1><p>This page provides links to tutorials, blog posts and code examples of the Genie programming language. It has been ported from the now-retired <a href="https://wiki.gnome.org/Projects/Genie/TutorialsBlogsExamples" target="_blank" rel="noreferrer">GNOME Wiki page</a>.</p><p>Many of these resources are several years old. They may still be useful but some links can be outdated or point to archived versions of long-gone websites.</p><div class="tip custom-block"><p class="custom-block-title">Help wanted</p><p>If you know of a useful resource (or a more up-to-date replacement for one of the links below), <a href="https://github.com/vala-lang/vala-docs/issues" target="_blank" rel="noreferrer">open an issue</a> or a pull request on the <a href="https://github.com/vala-lang/vala-docs" target="_blank" rel="noreferrer">Vala docs repository</a>.</p></div><h2 id="tutorials-and-articles" tabindex="-1">Tutorials and Articles <a class="header-anchor" href="#tutorials-and-articles" aria-label="Permalink to &quot;Tutorials and Articles&quot;">​</a></h2><ul><li><a href="./introduction.html">The Genie Programming Language Tutorial</a> - the official tutorial, ported into this documentation. the up-to-date reference manual maintained alongside the Vala compiler.</li><li><a href="https://github.com/avalanche-games/avalanche/wiki/Getting-Started-%28for-Linux-users%29" target="_blank" rel="noreferrer">Cross Compiling Vala/Genie from Linux to Android</a> - part of the Avalanche Games project; may be interesting for advanced users.</li><li><a href="https://geniedoc.blogspot.com/p/home.html" target="_blank" rel="noreferrer">Genie Doc (Español)</a> - &quot;Wiki de programación con Genie&quot;, an excellent set of tutorials and examples with screenshots and code samples; covers the basics and also GTK+3, GStreamer, Pango, Cairo and more.</li><li><a href="http://sprae.jogger.pl/2009/07/14/genie-python-vala/" target="_blank" rel="noreferrer">Genie = Python + Vala (Polski)</a> - some good introductory examples of using Gtk and Cairo.</li><li><a href="http://bkhome.org/genie/" target="_blank" rel="noreferrer">The Genie language</a> - by Barry Kauler; links to more detailed tutorials toward the bottom of the page.</li><li><a href="https://en.wikipedia.org/wiki/Genie_%28programming_language%29" target="_blank" rel="noreferrer">Genie (programming language)</a> - Wikipedia article.</li><li><a href="https://wiki.gnome.org/Projects/Genie/GtkGuiTutorial" target="_blank" rel="noreferrer">GTK GUI development in Genie</a> - a basic introduction from 2010.</li><li><a href="http://nnc3.com/LinuxMag/Magazine/Archive/2010/118/056-060_valagenie/article.html" target="_blank" rel="noreferrer">In the Bottle - Good performance and easy coding</a> - by Ankur Kumar, article published in 2010 in Linux Magazine.</li><li><a href="https://stackoverflow.com/questions/tagged/genie" target="_blank" rel="noreferrer">Newest &#39;genie&#39; Questions on Stack Overflow</a> - technical questions and answers.</li><li><a href="https://www.pihomeserver.fr/en/2014/05/10/raspberry-pi-home-server-installer-et-tester-le-langage-genie/" target="_blank" rel="noreferrer">Raspberry Pi Home Server - Install and test the Vala language / Genie</a> - a tutorial using Genie and the WiringPi GPIO interface library to blink a LED on the Raspberry Pi.</li><li><a href="http://puppylinux.org/wikka/GenieProgramming" target="_blank" rel="noreferrer">Vala and Genie Programming - PuppyLinux</a> - a basic introduction from the Puppy Linux project.</li></ul><h2 id="blogs-and-forum-posts" tabindex="-1">Blogs and Forum Posts <a class="header-anchor" href="#blogs-and-forum-posts" aria-label="Permalink to &quot;Blogs and Forum Posts&quot;">​</a></h2><ul><li><a href="https://web.archive.org/web/20260117092411/https://blog.darkoverlordofdata.com/2016/02/six-weeks-with-vala.html" target="_blank" rel="noreferrer">Six Weeks with Vala</a> - February 2016, blog post reviewing the author&#39;s experience with Vala and Genie: &quot;I found that Genie, the &#39;other&#39; language compiled by valac, is vastly underrated. Genie could be the next big thing...&quot;</li><li><a href="https://www.reddit.com/r/nim/comments/369a36/nim_vs_valagenie/" target="_blank" rel="noreferrer">Nim vs. Vala/Genie</a> - May 2015, Reddit post comparing <a href="https://nim-lang.org/" target="_blank" rel="noreferrer">Nim</a> with Vala and Genie.</li><li><a href="http://codingcraig.blogspot.com/2011/12/genie.html" target="_blank" rel="noreferrer">Genie - Coding Craig</a> - December 2011, an enthusiastic and critical overview.</li><li><a href="http://compsci.ca/v3/viewtopic.php?t=26633" target="_blank" rel="noreferrer">Vala/Genie versus Python opinion piece</a> - forum post highlighting the speed of a very simple compiled Genie program over Python.</li><li><a href="http://laviefrugale.blogspot.com/2010/07/genievala.html" target="_blank" rel="noreferrer">Genie/Vala</a> - July 2010, first impression of Genie and Vala.</li><li><a href="http://lukas.zapletalovi.com/2010/06/jazyk-genie.html" target="_blank" rel="noreferrer">Jazyk Genie (Polski)</a> - June 2010, introduction to Genie.</li><li><a href="http://jamiemcc.livejournal.com/12009.html" target="_blank" rel="noreferrer">Genie Improvements</a> - June 2008, the introduction of lists and dicts by Genie&#39;s creator Jamie McCracken.</li><li><a href="http://jamiemcc.livejournal.com/11749.html" target="_blank" rel="noreferrer">Introducing Genie - the smart programming language</a> - May 2008, by Jamie McCracken.</li></ul><h2 id="code-examples-and-utilities" tabindex="-1">Code Examples and Utilities <a class="header-anchor" href="#code-examples-and-utilities" aria-label="Permalink to &quot;Code Examples and Utilities&quot;">​</a></h2><ul><li><a href="https://launchpad.net/agendie" target="_blank" rel="noreferrer">AgenDie</a> - an address book with a GTK+3 front end.</li><li><a href="https://github.com/darkoverlordofdata/game-foo" target="_blank" rel="noreferrer">GameFoo</a> - &quot;A POC for an ECS game engine written in Vala/Genie&quot;.</li><li><a href="/genie/sample-code/">Genie sample code</a> — full sources hosted in this documentation (basic I/O, Cairo, GIO, LibSoup, XML, and more).</li><li><a href="http://onagat.hatenablog.com/entry/2015/06/07/001236" target="_blank" rel="noreferrer">Image viewer</a> - example of an image viewer written in Genie.</li><li><a href="http://onagat.hatenablog.com/entry/2015/06/19/124943" target="_blank" rel="noreferrer">Image viewer 2 (GtkStack)</a> - another example of an image viewer written in Genie.</li><li><a href="https://www.vim.org/scripts/script.php?script_id=2349" target="_blank" rel="noreferrer"><code>indent/genie.vim</code></a> - Vim text editor indent script for the Genie language.</li><li><a href="https://github.com/tliron/khovsgol/" target="_blank" rel="noreferrer">Khövsgöl Source Code</a> - a shared music player and library / playlist manager licensed under the GPL. A good example of using GTK, SQLite and GStreamer 1.0 in Genie. Provides integration with PulseAudio, JACK, IceCast, RTP, desktop, MPRIS and Zeroconf/Bonjour.</li><li><a href="https://github.com/darkoverlordofdata/shmupwarz-vala" target="_blank" rel="noreferrer">ShmupWars - Vala</a> - arcade-style game mostly written in Genie and some Vala, uses SDL 2.</li><li><a href="https://github.com/tobimensch/py2gs" target="_blank" rel="noreferrer"><code>py2gs</code></a> - a simple Bash script as a starting point to convert Python to Genie.</li><li><a href="https://github.com/sdl2-vapi/sdl2-vapi/tree/cb4df42eabdbf53702a178e048648d9ceaff14eb/examples/Example%202-%20Genie" target="_blank" rel="noreferrer">SDL 2.0 Example</a> - example of Genie code with the SDL 2.0 bindings. Makes use of a font, image and audio file.</li></ul><h2 id="communities" tabindex="-1">Communities <a class="header-anchor" href="#communities" aria-label="Permalink to &quot;Communities&quot;">​</a></h2><ul><li><a href="https://vala.dev/#community" target="_blank" rel="noreferrer">Vala Community</a> - chat rooms, forums and other community resources for Vala and Genie.</li><li><a href="https://stackoverflow.com/questions/tagged/genie" target="_blank" rel="noreferrer">Newest &#39;genie&#39; Questions on Stack Overflow</a></li></ul><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./introduction.html">Introduction to Genie</a> - language overview and tutorial.</li><li><a href="./developing-genie.html">Developing Genie</a> - guide to improving the Genie scanner and parser.</li></ul>',14)])])}const p=a(o,[["render",n]]);export{c as __pageData,p as default};
